import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CGregAndFriends solver = new CGregAndFriends();
        solver.solve(1, in, out);
        out.close();
    }

    static class CGregAndFriends {
        long mod = 1000000007L;
        long INF = 1000000000000000001L;
        long[][] nCr = new long[100][100];
        PrintWriter out;
        InputReader in;

        long f(long p, int a, int b, int c, int d) {
            p *= nCr[a][b];
            p %= mod;
            p *= nCr[c][d];
            p %= mod;
            return p;
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            this.out = out;
            this.in = in;
            int n = ni();
            int K = ni();
            int cnt1 = 0, cnt2 = 0;

            for (int i = 0; i < 100; i++) {
                for (int j = 0; j <= i; j++) {
                    if (j == 0 || j == i)
                        nCr[i][j] = 1;
                    else
                        nCr[i][j] = (nCr[i - 1][j] + nCr[i - 1][j - 1]) % mod;
                }
            }

            for (int i = 0; i < n; i++) {
                if (ni() == 50)
                    cnt1++;
                else
                    cnt2++;
            }

            long[][][] dist = new long[200][200][2];
            long[][][] dp = new long[200][200][2];
            for (int i = 0; i < 200; i++)
                for (int j = 0; j < 200; j++)
                    Arrays.fill(dist[i][j], INF);

            dist[0][0][0] = 0;
            dp[0][0][0] = 1;
            Queue<Tuple> pq = new PriorityQueue<Tuple>();
            pq.add(new Tuple(0, 0, 0, 0));

            while (!pq.isEmpty()) {
                Tuple cur = pq.poll();
                if (cur.d != dist[cur.x][cur.y][cur.z])
                    continue;
                int x = cur.x;
                int y = cur.y;
                int z = cur.z;
                long d = dist[x][y][z];

                if (z == 0) {
                    int remX = cnt1 - x;
                    int remY = cnt2 - y;
                    for (int i = 0; i <= remX; i++) {
                        for (int j = 0; j <= remY; j++) {
                            if (i + j == 0)
                                continue;
                            if (i * 50 + j * 100 > K)
                                break;
                            long ways = f(dp[x][y][z], remX, i, remY, j);
                            int nx = x + i;
                            int ny = y + j;
                            int nz = z ^ 1;
                            if (dist[nx][ny][nz] >= d + 1) {
                                if (dist[nx][ny][nz] > d + 1) {
                                    dist[nx][ny][nz] = d + 1;
                                    dp[nx][ny][nz] += ways;
                                    dp[nx][ny][nz] %= mod;
                                    pq.add(new Tuple(dist[nx][ny][nz], nx, ny, nz));
                                } else {
                                    dp[nx][ny][nz] += ways;
                                    dp[nx][ny][nz] %= mod;
                                }
                            }
                        }
                    }
                } else {
                    int remX = x;
                    int remY = y;
                    for (int i = 0; i <= remX; i++) {
                        for (int j = 0; j <= remY; j++) {
                            if (i + j == 0)
                                continue;
                            if (i * 50 + j * 100 > K)
                                break;
                            long ways = f(dp[x][y][z], remX, i, remY, j);
                            int nx = x - i;
                            int ny = y - j;
                            int nz = z ^ 1;
                            if (dist[nx][ny][nz] >= d + 1) {
                                if (dist[nx][ny][nz] > d + 1) {
                                    dist[nx][ny][nz] = d + 1;
                                    dp[nx][ny][nz] += ways;
                                    dp[nx][ny][nz] %= mod;
                                    pq.add(new Tuple(dist[nx][ny][nz], nx, ny, nz));
                                } else {
                                    dp[nx][ny][nz] += ways;
                                    dp[nx][ny][nz] %= mod;
                                }
                            }
                        }
                    }
                }
            }

            if (dist[cnt1][cnt2][1] == INF)
                pn(-1);
            else
                pn(dist[cnt1][cnt2][1]);
            pn(dp[cnt1][cnt2][1]);
        }

        int ni() {
            return in.nextInt();
        }

        void pn(long zx) {
            out.println(zx);
        }

        static class Tuple implements Comparable<Tuple> {
            long d;
            int x, y, z;

            Tuple(long d, int x, int y, int z) {
                this.d = d;
                this.x = x;
                this.y = y;
                this.z = z;
            }

            public int compareTo(Tuple other) {
                if (d != other.d)
                    return d < other.d ? -1 : 1;
                if (x != other.x)
                    return x - other.x;
                if (y != other.y)
                    return y - other.y;
                return z - other.z;
            }
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new UnknownError();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
